/*
 * The faces of the "instrument" typeface. Generated by `pnpm tokens` from design.json: do
 * not edit by hand.
 */
import { JetBrains_Mono, Onest, Source_Serif_4 } from "next/font/google";

const sans = Onest({
  variable: "--font-face-sans",
  subsets: ["latin"],
});

const mono = JetBrains_Mono({
  variable: "--font-face-mono",
  subsets: ["latin"],
});

// The face of the PDFs, for a document shown on screen. Not preloaded: only a sheet asks for it.
const document = Source_Serif_4({
  variable: "--font-face-document",
  subsets: ["latin"],
  preload: false,
});

/** The class names that declare the font variables; the root element carries them. */
export const fontVariables = [sans.variable, mono.variable, document.variable].join(" ");
